import argparse
import json
import keyword
import re
from pathlib import Path
from typing import Any

_GENERATED_HEADER = (
    "# This file is generated from the Cara Gateway OpenRPC specification.\n"
    "# Source: gateway/schema/gateway.openrpc.json\n"
    "# Do not edit this file manually; run cara-gateway-client-generate.\n"
)


def _ref_name(schema: dict[str, Any]) -> str:
    return schema["$ref"].rsplit("/", 1)[-1]


def _referenced_models(value: Any) -> set[str]:
    if isinstance(value, dict):
        names = {_ref_name(value)} if "$ref" in value else set()
        for nested in value.values():
            names.update(_referenced_models(nested))
        return names
    if isinstance(value, list):
        names: set[str] = set()
        for nested in value:
            names.update(_referenced_models(nested))
        return names
    return set()


def _literal(value: Any) -> str:
    if isinstance(value, str):
        return json.dumps(value)
    return repr(value)


def _union(types: list[str]) -> str:
    return " | ".join(dict.fromkeys(types))


def _python_type(
    schema: dict[str, Any] | bool,
    *,
    quote_refs: bool = True,
) -> str:
    if isinstance(schema, bool):
        return "Any"
    if "$ref" in schema:
        return _ref_name(schema)
    if "const" in schema:
        return f"Literal[{_literal(schema['const'])}]"
    variants = schema.get("anyOf") or schema.get("oneOf")
    if variants:
        result = _union(
            [_python_type(variant, quote_refs=quote_refs) for variant in variants]
        )
        discriminator = schema.get("discriminator", {}).get("propertyName")
        if discriminator:
            return (
                f"Annotated[{result}, Field(discriminator={_literal(discriminator)})]"
            )
        return result
    schema_type = schema.get("type")
    if schema_type == "string":
        if schema.get("format") == "uuid":
            return "UUID"
        if schema.get("format") == "date-time":
            return "datetime"
        return "str"
    if schema_type == "integer":
        return "int"
    if schema_type == "number":
        return "float"
    if schema_type == "boolean":
        return "bool"
    if schema_type == "null":
        return "None"
    if schema_type == "array":
        return f"list[{_python_type(schema.get('items', {}), quote_refs=quote_refs)}]"
    if schema_type == "object":
        value_type = _python_type(
            schema.get("additionalProperties", {}), quote_refs=quote_refs
        )
        return f"dict[str, {value_type}]"
    return "Any"


def _identifier(value: str) -> str:
    identifier = re.sub(r"\W", "_", value)
    if identifier[:1].isdigit() or keyword.iskeyword(identifier):
        identifier = f"{identifier}_"
    return identifier


def _enum_member(value: str | int) -> str:
    if isinstance(value, int):
        return f"VALUE_{'NEG_' if value < 0 else ''}{abs(value)}"
    return _identifier(value).upper()


def _render_enum(name: str, schema: dict[str, Any]) -> list[str]:
    values = schema["enum"]
    base = "IntEnum" if all(isinstance(value, int) for value in values) else "StrEnum"
    lines = [f"class {name}({base}):"]
    lines.extend(f"    {_enum_member(value)} = {_literal(value)}" for value in values)
    return lines


def _render_model(
    name: str,
    schema: dict[str, Any],
    discriminator_fields: dict[str, tuple[str, str]],
) -> list[str]:
    properties = schema.get("properties", {})
    required = set(schema.get("required", []))
    base = (
        "GatewayModel" if schema.get("additionalProperties") is False else "BaseModel"
    )
    lines = [f"class {name}({base}):"]
    ordered_properties = sorted(properties.items(), key=lambda item: item[0] != "type")
    for field_name, field_schema in ordered_properties:
        discriminator = discriminator_fields.get(name) if field_name == "type" else None
        if discriminator:
            enum_name, member_name = discriminator
            annotation = f"Literal[{enum_name}.{member_name}]"
        else:
            annotation = _python_type(field_schema)
        if field_name not in required and "default" not in field_schema:
            annotation = _union([annotation, "None"])
            default = "None"
        elif discriminator:
            default = f"{enum_name}.{member_name}"
        elif "default" in field_schema:
            default = _literal(field_schema["default"])
        else:
            default = None
        assignment = f" = {default}" if default is not None else ""
        lines.append(f"    {_identifier(field_name)}: {annotation}{assignment}")
    if len(lines) == 1:
        lines.append("    pass")
    return lines


def _render_alias(name: str, schema: dict[str, Any]) -> str:
    variants = schema.get("oneOf") or schema.get("anyOf")
    if not variants or len(variants) < 3:
        return f"type {name} = {_python_type(schema, quote_refs=False)}"
    variant_types = [_python_type(variant, quote_refs=False) for variant in variants]
    inline_union = " | ".join(variant_types)
    if len(inline_union) <= 72:
        union = f"    {inline_union}"
    else:
        union = "\n".join(
            f"    {variant}" if index == 0 else f"    | {variant}"
            for index, variant in enumerate(variant_types)
        )
    discriminator = schema.get("discriminator", {}).get("propertyName")
    if discriminator:
        return (
            f"type {name} = Annotated[\n"
            f"{union},\n"
            f"    Field(discriminator={_literal(discriminator)}),\n"
            "]"
        )
    return f"type {name} = (\n{union}\n)"


def _discriminator_definitions(
    schemas: dict[str, dict[str, Any]],
) -> tuple[list[str], dict[str, tuple[str, str]]]:
    enum_blocks: list[str] = []
    fields: dict[str, tuple[str, str]] = {}
    for alias_name, schema in schemas.items():
        discriminator = schema.get("discriminator")
        if not discriminator or discriminator.get("propertyName") != "type":
            continue
        enum_name = "EventType" if alias_name.endswith("Event") else f"{alias_name}Type"
        lines = [f"class {enum_name}(StrEnum):"]
        for value, reference in discriminator["mapping"].items():
            member_name = _enum_member(value)
            lines.append(f"    {member_name} = {_literal(value)}")
            fields[reference.rsplit("/", 1)[-1]] = (enum_name, member_name)
        enum_blocks.append("\n".join(lines))
    return enum_blocks, fields


def render_models(specification: dict[str, Any]) -> str:
    schemas = specification["components"]["schemas"]
    blocks, discriminator_fields = _discriminator_definitions(schemas)
    method_enum = ["class RpcMethod(StrEnum):"]
    method_enum.extend(
        f"    {_enum_member(method['name'])} = {_literal(method['name'])}"
        for method in specification["methods"]
    )
    blocks.append("\n".join(method_enum))
    blocks.append(
        'class GatewayModel(BaseModel):\n    model_config = ConfigDict(extra="forbid")'
    )
    aliases: list[tuple[str, dict[str, Any]]] = []
    for name, schema in schemas.items():
        if "enum" in schema:
            blocks.append("\n".join(_render_enum(name, schema)))
        elif schema.get("type") == "object":
            blocks.append("\n".join(_render_model(name, schema, discriminator_fields)))
        else:
            aliases.append((name, schema))
    blocks.extend(_render_alias(name, schema) for name, schema in aliases)
    model_names = [
        name for name, schema in schemas.items() if schema.get("type") == "object"
    ]
    rebuilds = "\n".join(f"{name}.model_rebuild()" for name in model_names)
    return (
        _GENERATED_HEADER + "from __future__ import annotations\n\n"
        "from datetime import datetime\n"
        "from enum import IntEnum, StrEnum\n"
        "from typing import Annotated, Any, Literal\n"
        "from uuid import UUID\n\n"
        "from pydantic import BaseModel, ConfigDict, Field\n\n\n"
        + "\n\n\n".join(blocks)
        + "\n\n\n"
        + rebuilds
        + "\n"
    )


def _pascal_case(value: str) -> str:
    return "".join(part.capitalize() for part in re.split(r"[._-]", value))


def _result_name(method: dict[str, Any]) -> str:
    return _ref_name(method["result"]["schema"])


def _params_name(method: dict[str, Any]) -> str:
    return _ref_name(method["x-cara-params-schema"])


def _render_operation(method: dict[str, Any]) -> list[str]:
    operation_name = _identifier(method["name"].split(".")[-1])
    params_name = _params_name(method)
    result_name = _result_name(method)
    lines = [f"    async def {operation_name}(", "        self,"]
    if method["params"]:
        lines.append("        *,")
    for parameter in method["params"]:
        annotation = _python_type(parameter["schema"])
        default = "" if parameter.get("required") else " = None"
        if not parameter.get("required"):
            annotation = _union([annotation, "None"])
        lines.append(
            f"        {_identifier(parameter['name'])}: {annotation}{default},"
        )
    lines.append(f"    ) -> {result_name}:")
    lines.append(f"        params = {params_name}(")
    lines.extend(
        f"            {_identifier(parameter['name'])}="
        f"{_identifier(parameter['name'])},"
        for parameter in method["params"]
    )
    lines.append("        )")
    lines.append("        result = await self._transport.request(")
    lines.append(f"            RpcMethod.{_enum_member(method['name'])},")
    lines.append('            params.model_dump(mode="json", exclude_none=True),')
    lines.append("        )")
    lines.append(f"        return {result_name}.model_validate(result)")
    return lines


def _namespace_class_name(namespace: str) -> str:
    if namespace == "turn":
        return "TurnsClient"
    return f"{_pascal_case(namespace)}Client"


def _group_methods(
    specification: dict[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {}
    for method in specification["methods"]:
        namespace = method["name"].split(".", 1)[0]
        grouped.setdefault(namespace, []).append(method)
    return grouped


def render_namespace(namespace: str, methods: list[dict[str, Any]]) -> str:
    class_name = _namespace_class_name(namespace)
    model_names = sorted(
        {
            "RpcMethod",
            *(_result_name(method) for method in methods),
            *(_params_name(method) for method in methods),
            *(
                model_name
                for method in methods
                for parameter in method["params"]
                for model_name in _referenced_models(parameter["schema"])
            ),
        }
    )
    if len(model_names) == 1:
        model_import = f"from gateway_client.models import {model_names[0]}\n"
    else:
        imports = ",\n    ".join(model_names)
        model_import = f"from gateway_client.models import (\n    {imports},\n)\n"
    lines = [
        f"class {class_name}:",
        "    def __init__(self, transport: RpcTransport) -> None:",
        "        self._transport = transport",
    ]
    for method in methods:
        lines.extend(["", *_render_operation(method)])
    return (
        _GENERATED_HEADER + "from typing import Any\n"
        "from uuid import UUID\n\n"
        + model_import
        + "from gateway_client.transport import RpcTransport\n\n\n"
        + "\n".join(lines)
        + "\n"
    )


def render_namespaces_init(grouped: dict[str, list[dict[str, Any]]]) -> str:
    imports = "\n".join(
        f"from .{namespace} import {_namespace_class_name(namespace)}"
        for namespace in grouped
    )
    exports = "\n".join(
        f'    "{_namespace_class_name(namespace)}",' for namespace in grouped
    )
    return f"{_GENERATED_HEADER}{imports}\n\n__all__ = [\n{exports}\n]\n"


def render_client(specification: dict[str, Any]) -> str:
    grouped = _group_methods(specification)
    namespace_imports = ",\n    ".join(
        _namespace_class_name(namespace) for namespace in grouped
    )
    assignments = "\n".join(
        f"        self.{_identifier(namespace)} = "
        f"{_namespace_class_name(namespace)}(transport)"
        for namespace in grouped
    )
    return (
        _GENERATED_HEADER + "from collections.abc import AsyncIterator\n"
        "from typing import Self\n\n"
        "from pydantic import TypeAdapter\n\n"
        "from gateway_client.models import SessionEventNotification\n"
        "from gateway_client.namespaces import (\n    " + namespace_imports + ",\n)\n"
        "from gateway_client.transport import RpcTransport, WebSocketTransport\n\n\n"
        "class GatewayClient:\n"
        "    def __init__(self, transport: RpcTransport) -> None:\n"
        "        self._transport = transport\n" + assignments + "\n\n"
        "    @classmethod\n"
        "    async def connect(cls, url: str) -> Self:\n"
        "        return cls(await WebSocketTransport.connect(url))\n\n"
        "    async def notifications(\n"
        "        self,\n"
        "    ) -> AsyncIterator[SessionEventNotification]:\n"
        "        adapter = TypeAdapter(SessionEventNotification)\n"
        "        async for message in self._transport.notifications():\n"
        "            yield adapter.validate_python(message)\n\n"
        "    async def close(self) -> None:\n"
        "        await self._transport.close()\n\n"
        "    async def __aenter__(self) -> Self:\n"
        "        return self\n\n"
        "    async def __aexit__(self, *args: object) -> None:\n"
        "        await self.close()\n"
    )


def generate(schema_path: Path, output_directory: Path, *, check: bool = False) -> bool:
    specification = json.loads(schema_path.read_text(encoding="utf-8"))
    grouped = _group_methods(specification)
    files = {
        output_directory / "models.py": render_models(specification),
        output_directory / "client.py": render_client(specification),
        output_directory / "namespaces" / "__init__.py": render_namespaces_init(
            grouped
        ),
    }
    files.update(
        {
            output_directory / "namespaces" / f"{namespace}.py": render_namespace(
                namespace, methods
            )
            for namespace, methods in grouped.items()
        }
    )
    changed = False
    for path, content in files.items():
        if path.exists() and path.read_text(encoding="utf-8") == content:
            continue
        changed = True
        if not check:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
    return changed


def main() -> None:
    parser = argparse.ArgumentParser(description="Generate the typed Gateway client")
    parser.add_argument("schema", type=Path)
    parser.add_argument(
        "--output",
        type=Path,
        default=Path("gateway_client/src/gateway_client"),
    )
    parser.add_argument("--check", action="store_true")
    arguments = parser.parse_args()
    changed = generate(arguments.schema, arguments.output, check=arguments.check)
    if arguments.check and changed:
        parser.error("generated client is out of date")


if __name__ == "__main__":
    main()
